var t=`1029-mi-quang`;var n=`world-1029`;var s=`VN`;var a=`southeast-asia`;var r=4;var o=69;var l={en:`Mi Quang`,ua:`Мі куанг`};var g={en:`Mi Quang is a dish from Vietnam prepared with pork shoulder, fish sauce, shallot, garlic. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Мі куанг, страва кухні країни В'єтнам, яку готують із таких продуктів: свиняча лопатка, рибний соус, цибуля шалот, часник. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 35 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 35 хвилин.`,t:[`marinating`],m:35,i:[[`pork-shoulder`,430,`g`],[`ground-turmeric`,4,`g`],[`fish-sauce`,26,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`shallot`,130,`g`],[`garlic`,4,`clove`],[`sunflower-oil`,35,`ml`],[`shrimp`,290,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 15 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 15 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:15,i:[[`chicken-stock`,480,`ml`],[`fish-sauce`,22,`ml`]]},{en:`Cook the listed ingredients in simmering water for about 6 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 6 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:6,i:[[`rice-noodles`,420,`g`],[`water`,1e3,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`peanut`,75,`g`],[`cilantro`,25,`g`],[`mint`,20,`g`],[`lettuce`,140,`g`]]}];var d={slug:t,id:n,country:`VN`,region:a,servings:4,minutes:69,title:l,text:g,steps:u};export{s as country,d as default,n as id,o as minutes,a as region,r as servings,t as slug,u as steps,g as text,l as title};